import{_ as e,o as t,c as i,a2 as n}from"./chunks/framework.EUByU7Iq.js";const p=JSON.parse('{"title":"第一章 一般规定","description":"","frontmatter":{"title":"第一章 一般规定","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/diyifenbian：tongze（diyizhang：yibanguiding）（wuquan）.md","filePath":"blogs/CC/第一分编：通则（第一章：一般规定）（物权）.md"}'),_={name:"blogs/CC/diyifenbian：tongze（diyizhang：yibanguiding）（wuquan）.md"};function o(r,a,d,s,l,h){return t(),i("div",null,[...a[0]||(a[0]=[n('<h3 id="第二百零五条" tabindex="-1">第二百零五条 <a class="header-anchor" href="#第二百零五条" aria-label="Permalink to &quot;第二百零五条&quot;">​</a></h3><p>本编调整因物的归属和利用产生的民事关系。</p><h3 id="第二百零六条" tabindex="-1">第二百零六条 <a class="header-anchor" href="#第二百零六条" aria-label="Permalink to &quot;第二百零六条&quot;">​</a></h3><p>国家坚持和完善公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制等社会主义基本经济制度。 国家巩固和发展公有制经济，鼓励、支持和引导非公有制经济的发展。 国家实行社会主义市场经济，保障一切市场主体的平等法律地位和发展权利。</p><h3 id="第二百零七条" tabindex="-1">第二百零七条 <a class="header-anchor" href="#第二百零七条" aria-label="Permalink to &quot;第二百零七条&quot;">​</a></h3><p>国家、集体、私人的物权和其他权利人的物权受法律平等保护，任何组织或者个人不得侵犯。</p><h3 id="第二百零八条" tabindex="-1">第二百零八条 <a class="header-anchor" href="#第二百零八条" aria-label="Permalink to &quot;第二百零八条&quot;">​</a></h3><p>不动产物权的设立、变更、转让和消灭，应当依照法律规定登记。动产物权的设立和转让，应当依照法律规定交付。</p>',8)])])}const u=e(_,[["render",o]]);export{p as __pageData,u as default};
